def evaluate(f):
    p = simulate_move(f)
    if p.get("game_over"):
        w = p.get("winner")
        if w == "white": return 100000
        elif w == "black": return -100000
        else: return 0
    sq = p["squares"]
    val = {"P":100,"N":320,"B":330,"R":500,"Q":900,"K":0}
    score = 0
    for s,piece in sq.items():
        sign = 1 if piece.isupper() else -1
        score += sign * val.get(piece.upper(),0)
        if s in ("d4","e4","d5","e5"):
            score += sign * 12
    if p.get("in_check"):
        score += -25 if p["turn"]=="white" else 25
    return score

best = None; best_move = None
for c in cands:
    aw = simulate_move(fen, c)
    if aw.get("game_over"):
        sc = evaluate(aw["fen"])
    else:
        reps = sorted(aw["legal_moves"])
        sc = min(evaluate(simulate_move(aw["fen"], r)["fen"]) for r in reps)
    if best is None or sc > best:
        best = sc; best_move = c
        print("new best", c, sc)

print("BEST", best_move, best)
play_move(best_move)
"}

